def remove(self, sku, qty):
        """Remove stock. The item stays in the inventory (qty 0) when fully removed."""
        if sku not in self.items:
            raise KeyError(sku)
        item = self.items[sku]
        if qty > item.qty:
            raise ValueError("insufficient stock")
        item.qty -= qty
        if item.qty == 0:
            del self.items[sku]
        return item

